"""Module 03 concepts: basic op-amp circuits (Floyd 9e Ch.13)."""
from lib import K
M = 'm03'
K('m03-comparator', M, ('Mạch so sánh', 'Comparators'),
  ('Op-amp không hồi tiếp so điện áp vào với điện áp tham chiếu; ngõ ra bão hoà ở mức dương hoặc âm tuỳ dấu của hiệu. Ngưỡng bằng không (zero-level) hoặc bằng Vref (nonzero-level).', 'An open-loop op-amp compares the input voltage with a reference; the output saturates positive or negative according to the sign of the difference. The threshold is zero (zero-level) or Vref (nonzero-level).'),
  facts=[('Vin > Vref → Vout ≈ +Vsat (ngõ vào không đảo)', ('Đảo ngõ vào thì đảo mức ra.', 'Swapping the inputs swaps the output level.')), ('Giới hạn: |Vout| = VZ + 0,7 V (zener hai chiều)', ('Mạch so sánh có giới hạn ngõ ra.', 'Bounded comparator.'))],
  steps=[('Xác định ngưỡng (0 hay Vref, hoặc bộ chia điện trở).', 'Find the threshold (0, Vref, or from a resistor divider).'), ('So Vin với ngưỡng cho từng mẫu thời gian rồi vẽ ngõ ra.', 'Compare Vin with the threshold sample by sample and sketch the output.')],
  traps=[('Quên đảo mức ra khi tín hiệu vào ngõ (−).', 'Forgetting to flip the output when the signal is on the (−) input.'), ('Cho rằng ngõ ra trung gian: ngõ ra chỉ có hai mức.', 'Expecting intermediate outputs: there are only two levels.')],
  angles=[('Vẽ ngõ ra của mạch so sánh với sin vào.', 'Sketch the comparator output for a sine input.'), ('Ngưỡng của mạch so sánh có Vref = 2 V.', 'The threshold of a comparator with Vref = 2 V.')],
  topics=['Comparators and hysteresis'], kw=['comparator', 'threshold', 'reference voltage', 'zero-level detector', 'nonzero-level', 'saturate', 'bounded', 'zener limiter', 'window'], kwv=['mạch so sánh', 'ngưỡng', 'điện áp tham chiếu', 'bão hoà', 'bộ so sánh'],
  src=['Floyd 9e §13–1'], related=['m03-hysteresis', 'm01-opamp-logic'], chk='comparator')
K('m03-hysteresis', M, ('Hysteresis và mạch Schmitt trigger', 'Hysteresis and the Schmitt trigger'),
  ('Hồi tiếp dương cho hai ngưỡng khác nhau (UTP và LTP) để ngõ ra không dao động quanh ngưỡng khi có nhiễu.', 'Positive feedback gives two different thresholds (UTP and LTP) so noise around the threshold does not make the output chatter.'),
  facts=[('V_UTP = R₂/(R₁ + R₂)·(+Vout(max)) ,  V_LTP = R₂/(R₁ + R₂)·(−Vout(max))', ('Ngưỡng trên và dưới.', 'Upper and lower trip points.')), ('V_HYS = V_UTP − V_LTP', ('Độ rộng vòng trễ.', 'Width of the hysteresis loop.'))],
  steps=[('Tính B = R₂/(R₁ + R₂).', 'Compute B = R₂/(R₁ + R₂).'), ('Nhân B với ±Vout(max) để có UTP và LTP.', 'Multiply B by ±Vout(max) for UTP and LTP.'), ('Ngõ ra đổi mức khi Vin vượt UTP (lên) hoặc LTP (xuống).', 'The output switches when Vin crosses UTP (rising) or LTP (falling).')],
  traps=[('Dùng cùng một ngưỡng cho cả hai chiều.', 'Using one threshold for both directions.'), ('Lẫn R₁ và R₂ trong tỉ số B.', 'Swapping R₁ and R₂ in B.')],
  angles=[('Tính UTP, LTP, V_HYS cho R₁, R₂ và Vout(max) cho trước.', 'Compute UTP, LTP and V_HYS for given R₁, R₂ and Vout(max).'), ('Vì sao dùng hysteresis?', 'Why use hysteresis?')],
  topics=['Comparators and hysteresis'], kw=['hysteresis', 'schmitt trigger', 'upper trip point', 'lower trip point', 'utp', 'ltp', 'positive feedback', 'noise immunity'], kwv=['hysteresis', 'vòng trễ', 'schmitt', 'ngưỡng trên', 'ngưỡng dưới', 'hồi tiếp dương'],
  src=['Floyd 9e §13–1'], related=['m03-comparator', 'm04-feedback'], chk='hysteresis')
K('m03-summing', M, ('Mạch cộng đảo', 'Summing amplifier'),
  ('Mạch đảo có nhiều ngõ vào qua các điện trở Ri nối vào đất ảo; ngõ ra là tổng có trọng số đảo dấu của các ngõ vào.', 'An inverting amplifier with several inputs through resistors Ri into the virtual ground; the output is the inverted weighted sum of the inputs.'),
  facts=[('VOUT = −(Rf/Ri)(V₁ + V₂ + … + Vₙ)', ('Mọi Ri bằng nhau.', 'All Ri equal.')), ('Rf = Ri → cộng đơn vị', ('Độ lợi mỗi ngõ bằng −1.', 'Each input has gain −1.'))],
  steps=[('Đất ảo: dòng vào mỗi nhánh = Vk/Rk, cộng các dòng.', 'Virtual ground: each branch current = Vk/Rk; add the currents.'), ('Nhân tổng dòng với −Rf.', 'Multiply the total current by −Rf.')],
  traps=[('Quên dấu âm.', 'Forgetting the minus sign.'), ('Cho rằng các ngõ vào ảnh hưởng lẫn nhau: đất ảo cách ly chúng.', 'Thinking the inputs affect one another: the virtual ground isolates them.')],
  angles=[('Ba ngõ vào 1 V, 2 V, 3 V với Rf = Ri: ngõ ra?', 'Three inputs 1 V, 2 V, 3 V with Rf = Ri: output?'), ('Chọn Rf cho mạch cộng đơn vị.', 'Pick Rf for a unity adder.')],
  topics=['Summing, averaging, scaling amplifiers'], kw=['summing amplifier', 'adder', 'summing', 'sum of voltages', 'unity adder', 'virtual ground'], kwv=['mạch cộng', 'khuếch đại cộng', 'tổng điện áp', 'cộng đơn vị'],
  src=['Floyd 9e §13–2'], related=['m03-scaling', 'm03-averaging', 'm02-inverting'], chk='summing')
K('m03-averaging', M, ('Mạch trung bình', 'Averaging amplifier'),
  ('Mạch cộng với Rf/Ri = 1/n cho ngõ ra là trung bình đảo dấu của n ngõ vào.', 'A summing amplifier with Rf/Ri = 1/n outputs the inverted average of n inputs.'),
  facts=[('Rf/Ri = 1/n → VOUT = −(V₁ + … + Vₙ)/n', ('n = số ngõ vào.', 'n = number of inputs.'))],
  steps=[('Đếm số ngõ vào n rồi đặt Rf = Ri/n.', 'Count the inputs n and set Rf = Ri/n.')],
  traps=[('Quên đảo dấu: ngõ ra là trung bình âm.', 'Forgetting the inversion: the output is the negative average.')],
  angles=[('Chọn Rf để trung bình bốn ngõ vào với Ri = 10 kΩ.', 'Choose Rf to average four inputs with Ri = 10 kΩ.')],
  topics=['Summing, averaging, scaling amplifiers'], kw=['averaging amplifier', 'average', 'mean', 'rf/ri = 1/n'], kwv=['mạch trung bình', 'trung bình', 'giá trị trung bình'],
  src=['Floyd 9e §13–2'], related=['m03-summing'], chk='averaging')
K('m03-scaling', M, ('Mạch cộng có trọng số và D/A', 'Scaling adder and D/A conversion'),
  ('Mỗi ngõ vào có Ri riêng nên có trọng số Rf/Rk riêng; trọng số nhị phân 1, 2, 4, 8… là bộ chuyển đổi D/A (hoặc dùng thang R/2R chỉ cần hai giá trị điện trở).', 'Each input has its own Rk, hence its own weight Rf/Rk; binary weights 1, 2, 4, 8… make a D/A converter (or an R/2R ladder that needs only two resistor values).'),
  facts=[('VOUT = −(Rf/R₁·V₁ + Rf/R₂·V₂ + … + Rf/Rₙ·Vₙ)', ('Trọng số của ngõ k là Rf/Rk.', 'The weight of input k is Rf/Rk.')), ('Rk = Rf/trọng số', ('Chọn Rk theo trọng số mong muốn.', 'Pick Rk from the wanted weight.'))],
  steps=[('Viết trọng số mong muốn của từng ngõ.', 'Write the wanted weight of each input.'), ('Đặt Rk = Rf/trọng số, rồi kiểm lại tổng.', 'Set Rk = Rf/weight, then check the sum.')],
  traps=[('Đảo ngược: ngõ vào có trọng số lớn cần điện trở NHỎ.', 'Reversing it: a large weight needs a SMALL resistor.')],
  angles=[('Thiết kế mạch cộng có trọng số 1, 2, 4.', 'Design a scaling adder with weights 1, 2, 4.'), ('Ngõ ra của DAC 4 bit với mã cho trước.', 'Output of a 4-bit DAC for a given code.')],
  topics=['Summing, averaging, scaling amplifiers'], kw=['scaling adder', 'weighted sum', 'weights', 'dac', 'd/a', 'binary weighted', 'r/2r', 'ladder'], kwv=['mạch cộng có trọng số', 'trọng số', 'dac', 'd/a', 'thang r/2r', 'chuyển đổi số sang tương tự'],
  src=['Floyd 9e §13–2'], related=['m03-summing', 'm05-adc-dac'], chk='scaling')
K('m03-integrator', M, ('Mạch tích phân', 'Integrator'),
  ('Mạch đảo có tụ C ở hồi tiếp: ngõ ra là tích phân của ngõ vào (đảo dấu). Bước nhảy → đường dốc; sóng vuông → sóng tam giác.', 'An inverting stage with a capacitor C in the feedback: the output is the integral of the input (inverted). Step → ramp; square wave → triangular wave.'),
  facts=[('ΔVout/Δt = −Vin/(Ri·C)', ('Độ dốc của đường dốc với Vin không đổi.', 'Ramp slope for a constant Vin.')), ('Vout(t) = −(1/RiC)∫Vin dt', ('Dạng tích phân tổng quát.', 'General integral form.'))],
  steps=[('Tính độ dốc −Vin/(Ri·C) (V/s), đổi đơn vị trước.', 'Compute the slope −Vin/(Ri·C) in V/s, converting units first.'), ('Ngõ ra = độ dốc × thời gian, bị chặn bởi mức bão hoà.', 'Output = slope × time, clipped at the saturation level.')],
  traps=[('Quên dấu âm của độ dốc.', 'Forgetting the minus sign of the slope.'), ('Bỏ qua trôi một chiều: không có điện trở song song với C thì sai số tích luỹ.', 'Ignoring dc drift: without a resistor across C the error accumulates.')],
  angles=[('Vin = 1 V, Ri = 10 kΩ, C = 0,1 μF: độ dốc?', 'Vin = 1 V, Ri = 10 kΩ, C = 0.1 μF: slope?'), ('Dạng sóng ra khi vào sóng vuông.', 'Output waveform for a square-wave input.')],
  topics=['Integrator'], kw=['integrator', 'ramp', 'capacitor feedback', 'triangular', 'integrate', 'drift'], kwv=['mạch tích phân', 'tích phân', 'đường dốc', 'tam giác', 'tụ hồi tiếp'],
  src=['Floyd 9e §13–3'], related=['m03-differentiator', 'm07-relaxation'], chk='integrator')
K('m03-differentiator', M, ('Mạch vi phân', 'Differentiator'),
  ('Mạch đảo có tụ C ở ngõ vào và Rf ở hồi tiếp: ngõ ra tỉ lệ với tốc độ đổi của ngõ vào (đảo dấu). Đường dốc → mức một chiều; tam giác → sóng vuông.', 'An inverting stage with the capacitor C at the input and Rf in the feedback: the output is proportional to the rate of change of the input (inverted). Ramp → dc level; triangle → square wave.'),
  facts=[('Vout = −Rf·C·(ΔVin/Δt)', ('Tỉ lệ với đạo hàm của ngõ vào.', 'Proportional to the derivative of the input.'))],
  steps=[('Tính ΔVin/Δt từ dạng sóng vào.', 'Compute ΔVin/Δt from the input waveform.'), ('Nhân với −Rf·C.', 'Multiply by −Rf·C.')],
  traps=[('Nhầm vai trò của R và C với mạch tích phân.', 'Swapping the roles of R and C with the integrator.'), ('Mạch vi phân khuếch đại nhiễu tần số cao.', 'A differentiator amplifies high-frequency noise.')],
  angles=[('Vào đường dốc 2 V/ms, Rf = 10 kΩ, C = 0,1 μF: ngõ ra?', 'Ramp input 2 V/ms, Rf = 10 kΩ, C = 0.1 μF: output?'), ('Ngõ ra khi vào sóng tam giác.', 'Output for a triangular input.')],
  topics=['Differentiator'], kw=['differentiator', 'differentiate', 'derivative', 'rate of change', 'spike'], kwv=['mạch vi phân', 'vi phân', 'đạo hàm', 'tốc độ thay đổi', 'xung nhọn'],
  src=['Floyd 9e §13–3'], related=['m03-integrator'], chk='differentiator')
